style.css:
/* -------------------------------- */
/* Курсор с cursor.cc для Stylish   */
/* -------------------------------- */

/* Основной курсор на весь сайт */
body, a, button, input, textarea {
    cursor: url("data:image/x-icon;base64,") 16 16, auto;
    transition: transform 0.1s; /* плавное возвращение */
}

/* Эффект уменьшения при клике */
a:active,
button:active,
input:active,
textarea:active {
    transform: scale(0.7); /* уменьшаем курсор при нажатии */
}
